        print(f"  {g(row,'行业类别代码')} {g(row,'行业类别名称')} | {g(row,'电站锅炉/燃气轮机类型')} | fuel1={g(row,'燃料一类型')} {g(row,'燃料一消耗量')} {g(row,'燃料一消耗量单位')}")

