header = [ws.cell(row=1, column=c).value for c in range(1, ws.max_column + 1)]
seen = {}
uniq_header = []
for h in header:
    if h in seen:
        seen[h] += 1
        uniq_header.append(f"{h}#{seen[h]}")
    else:
        seen[h] = 1
        uniq_header.append(h)
H = {n: i for i, n in enumerate(uniq_header)}
rows = []
for r in range(2, ws.max_row + 1):
    rows.append([ws.cell(row=r, column=c).value for c in range(1, ws.max_column + 1)])
def g(row, name): return row[H[name]]

# fuel units for all fuel types
fu = collections.Counter()
for row in rows:
    for suffix in ('燃料一', '燃料二'):
        t = g(row, f'{suffix}类型')
        u = g(row, f'{suffix}消耗量单位')
        if t is not None:
            fu[(t, u)] += 1
print("=== (fuel, unit) pairs ===")
for k, v in sorted(fu.items(), key=lambda x: -x[1]):
    print(f"  {k}: {v}")

# negative or weird activity values
print("\n=== negative activity values ===")
for row in rows:
    for suffix in ('燃料一', '燃料二'):
        v = g(row, f'{suffix}消耗量')
        if isinstance(v, (int, float)) and v < 0:
            print("  NEG", g(row,'行业类别代码'), suffix, v)
        elif isinstance(v, str) and v.strip().lstrip('-').replace('.','',1).isdigit() and float(v) < 0:
            print("  NEGstr", g(row,'行业类别代码'), suffix, v)
oth = [g(row,'其他燃料消耗总量（吨标准煤）') for row in rows if isinstance(g(row,'其他燃料消耗总量（吨标准煤）'), (int,float)) and g(row,'其他燃料消耗总量（吨标准煤）') < 0]
print("  negative other-fuel:", oth)

# coal rows with 燃烧方式 None or 其他 (among equipped rows)
print("\n=== coal-fuel equipped rows with combustion None/其他 ===")
coal_types = ('一般烟煤', '无烟煤', '原煤', '褐煤')
for row in rows:
    ib, pb = g(row, '工业锅炉类型'), g(row, '电站锅炉/燃气轮机类型')
    if ib is None and pb is None:
        continue
    f1, f2 = g(row, '燃料一类型'), g(row, '燃料二类型')
